1	<!doctype html>
2	<html lang="en">
3	<head>
4	<meta charset="utf-8">
5	<meta name="viewport" content="width=device-width, initial-scale=1">
6	{% if shop %}<meta name="lw-shop" content="{{ shop }}">
7	{% endif %}<title>{% if page == "privacy" %}Privacy · {% elif page == "thanks" %}Order received · {% endif %}{{ p.name }}</title>
8	<meta name="description" content="{{ p.tagline or p.about[:150] }}">
9	<meta property="og:title" content="{{ p.name }}">
10	<meta property="og:description" content="{{ p.tagline }}">
11	<meta name="theme-color" content="#fbf8f3">
12	{#
13	  ONE template for every seller. Nothing here may be specific to one business or one trade:
14	  every word on the page comes from the seller's profile, or is generic shop wording.
15	  Category colours come from the fixed palette below, picked by position (c0..c5), never per business.
16	#}
17	<style>
18	  :root {
19	    --bg: #fbf8f3; --paper: #ffffff; --ink: #1d1a16; --ink-2: #57514a; --muted: #7a736b;
20	    --line: #ebe4da; --line-2: #ddd4c8; --primary: #1d1a16; --primary-ink: #ffffff;
21	    --wa: #128c4a; --focus: #2563eb; --radius: 18px; --radius-sm: 12px;
22	    --shadow: 0 1px 2px rgba(40,30,20,.05), 0 10px 30px -18px rgba(40,30,20,.25);
23	    --serif: "Iowan Old Style", "Palatino Linotype", Palatino, Georgia, "Noto Serif", serif;
24	    --sans: system-ui, -apple-system, "Segoe UI", Roboto, "Noto Sans", "Helvetica Neue", sans-serif;
25	    /* Fixed category palette (soft background, strong ink), assigned by position. */
26	    --c0-bg: #fde8d7; --c0-ink: #9a3412;
27	    --c1-bg: #dff3e4; --c1-ink: #166534;
28	    --c2-bg: #e3ecfb; --c2-ink: #1e40af;
29	    --c3-bg: #f6e3f0; --c3-ink: #9d174d;
30	    --c4-bg: #fbf1c7; --c4-ink: #854d0e;
31	    --c5-bg: #e5f4f4; --c5-ink: #115e59;
32	  }
33	  * { box-sizing: border-box; }
34	  html { scroll-behavior: smooth; -webkit-text-size-adjust: 100%; }
35	  @media (prefers-reduced-motion: reduce) { html { scroll-behavior: auto; } * { transition: none !important; } }
36	  body { margin: 0; background: var(--bg); color: var(--ink); font: 16px/1.55 var(--sans);
37	    -webkit-font-smoothing: antialiased; overflow-wrap: anywhere; }
38	  a { color: inherit; }
39	  .wrap { max-width: 1120px; margin: 0 auto; padding: 0 16px; }
40	  @media (min-width: 720px) { .wrap { padding: 0 28px; } }
41	
42	  /* Top bar */
43	  header.bar { position: sticky; top: 0; z-index: 10; background: rgba(251,248,243,.92);
44	    backdrop-filter: saturate(1.4) blur(8px); -webkit-backdrop-filter: saturate(1.4) blur(8px);
45	    border-bottom: 1px solid var(--line); }
46	  header.bar .wrap { display: flex; align-items: center; justify-content: space-between; height: 60px; gap: 12px; }
47	  .brand { display: flex; align-items: center; gap: 10px; min-width: 0; font-weight: 650; text-decoration: none; }
48	  .brand span { white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
49	  .mono { flex: none; display: grid; place-items: center; border-radius: 10px; font-family: var(--serif);
50	    font-weight: 700; background: var(--c0-bg); color: var(--c0-ink); letter-spacing: .02em; }
51	  .brand .mono { width: 34px; height: 34px; font-size: 14px; }
52	  nav.links { display: none; gap: 22px; font-size: 15px; color: var(--ink-2); }
53	  nav.links a { text-decoration: none; }
54	  nav.links a:hover { color: var(--ink); }
55	  @media (min-width: 900px) { nav.links { display: flex; } }
56	
57	  /* Buttons */
58	  .btn { display: inline-flex; align-items: center; justify-content: center; gap: 8px; min-height: 46px;
59	    padding: 10px 20px; border-radius: 999px; border: 1px solid transparent; font: inherit; font-weight: 600;
60	    text-decoration: none; cursor: pointer; transition: transform .12s ease, background-color .15s ease, box-shadow .15s ease;
61	    -webkit-tap-highlight-color: transparent; white-space: nowrap; }
62	  .btn:active { transform: scale(.97); }
63	  .btn-primary { background: var(--primary); color: var(--primary-ink); }
64	  .btn-primary:hover { background: #3a342d; }
65	  .btn-wa { background: var(--wa); color: #fff; }
66	  .btn-wa:hover { background: #0f7a40; }
67	  .btn-line { background: var(--paper); color: var(--ink); border-color: var(--line-2); }
68	  .btn-line:hover { border-color: var(--ink); }
69	  .btn-sm { min-height: 38px; padding: 6px 16px; font-size: 15px; }
70	  .btn-block { width: 100%; }
71	  .btn svg { width: 18px; height: 18px; flex: none; }
72	  :focus-visible { outline: 3px solid var(--focus); outline-offset: 2px; }
73	
74	  /* Hero */
75	  .hero { padding: 36px 0 28px; display: grid; gap: 22px; }
76	  .hero .mono { display: none; }
77	  .hero h1 { font-family: var(--serif); font-weight: 700; font-size: clamp(34px, 8.5vw, 60px); line-height: 1.04;
78	    letter-spacing: -.02em; margin: 0; }
79	  .hero .tagline { font-size: clamp(18px, 2.4vw, 21px); color: var(--ink-2); margin: 10px 0 0; max-width: 36em; }
80	  .meta { display: flex; flex-wrap: wrap; gap: 6px 16px; margin: 12px 0 0; padding: 0; list-style: none; color: var(--muted); font-size: 15px; }
81	  .meta li { display: inline-flex; align-items: flex-start; gap: 6px; }
82	  .meta svg { width: 16px; height: 16px; flex: none; margin-top: 3px; }
83	  .badges { display: flex; flex-wrap: wrap; gap: 8px; margin: 0; padding: 0; list-style: none; }
84	  .badges li { padding: 6px 12px; border-radius: 999px; background: var(--paper); border: 1px solid var(--line-2);
85	    font-size: 14px; font-weight: 600; color: var(--ink-2); }
86	  .cta { display: flex; flex-wrap: wrap; gap: 10px; }
87	  @media (min-width: 720px) {
88	    .hero { grid-template-columns: auto 1fr; align-items: start; column-gap: 28px; padding: 64px 0 44px; }
89	    .hero .mono { display: grid; width: 96px; height: 96px; font-size: 36px; border-radius: 26px; }
90	    .hero > :not(.mono) { grid-column: 2; }
91	  }
92	
93	  /* Page grid: menu left, order panel right on wide screens */
94	  .layout { display: grid; grid-template-columns: minmax(0, 1fr); gap: 28px; padding-bottom: 40px; }
95	  @media (min-width: 960px) {
96	    .layout { grid-template-columns: minmax(0, 1fr) 380px; gap: 40px; align-items: start; }
97	    .panel { position: sticky; top: 84px; }
98	  }
99	  .section-h { font-family: var(--serif); font-size: 28px; line-height: 1.15; margin: 0 0 6px; letter-spacing: -.01em; }
100	  .section-sub { color: var(--muted); margin: 0 0 18px; font-size: 15px; }
101	
102	  /* Category quick links */
103	  .chips { display: flex; gap: 8px; overflow-x: auto; padding: 2px 0 14px; margin: 0; list-style: none; scrollbar-width: none; }
104	  .chips::-webkit-scrollbar { display: none; }
105	  .chips a { display: inline-block; padding: 7px 14px; border-radius: 999px; font-size: 14px; font-weight: 600;
106	    text-decoration: none; white-space: nowrap; }
107	
108	  /* Menu */
109	  .cat { margin: 0 0 22px; scroll-margin-top: 80px; }
110	  .cat-h { display: flex; align-items: center; gap: 10px; margin: 0 0 10px; font-size: 15px; font-weight: 700; }
111	  .cat-h .dot { width: 10px; height: 10px; border-radius: 3px; }
112	  .cat-h .count { color: var(--muted); font-weight: 500; font-size: 14px; }
113	  .items { list-style: none; margin: 0; padding: 0; background: var(--paper); border: 1px solid var(--line);
114	    border-radius: var(--radius); box-shadow: var(--shadow); overflow: hidden; }
115	  .item { display: grid; grid-template-columns: minmax(0, 1fr) auto; gap: 6px 16px; align-items: center; padding: 14px 16px; }
116	  .item + .item { border-top: 1px solid var(--line); }
117	  .item.has-photo { grid-template-columns: 72px minmax(0, 1fr) auto; }
118	  .item-photo { width: 72px; height: 72px; object-fit: cover; border-radius: 12px; background: var(--line); }
119	  .gallery { list-style: none; margin: 0 0 28px; padding: 0 0 6px; display: grid; grid-auto-flow: column;
120	    grid-auto-columns: min(80%, 340px); gap: 12px; overflow-x: auto; scroll-snap-type: x mandatory; }
121	  .gallery li { scroll-snap-align: start; }
122	  .gallery img { display: block; width: 100%; height: auto; aspect-ratio: 4 / 3; object-fit: cover; border-radius: 16px;
123	    background: var(--line); }
124	  @media (min-width: 900px) {
125	    .gallery { grid-auto-flow: row; grid-template-columns: repeat(3, 1fr); overflow: visible; }
126	    .gallery.n1 { grid-template-columns: minmax(0, 560px); }
127	    .gallery.n2, .gallery.n4 { grid-template-columns: repeat(2, 1fr); }
128	  }
129	  .item .name { font-weight: 600; line-height: 1.35; }
130	  .item .desc { font-size: 14px; color: var(--muted); margin-top: 2px; }
131	  .item .price { font-weight: 700; margin-top: 4px; font-variant-numeric: tabular-nums; }
132	  .item .price small { font-weight: 500; color: var(--muted); font-size: 13px; }
133	  .item.chosen { background: #fffdf8; }
134	  /* Long lists: two columns on wide screens (1px gaps draw the dividers). */
135	  .items.dense { display: grid; gap: 1px; background: var(--line); }
136	  .items.dense .item { background: var(--paper); border-top: 0; }
137	  .items.dense .item.chosen { background: #fffdf8; }
138	  @media (min-width: 720px) { .items.dense { grid-template-columns: 1fr 1fr; } }
139	  .find { margin: 0 0 14px; }
140	  .find label { display: block; margin-bottom: 4px; }
141	  .find input { max-width: 360px; }
142	  .find-none { color: var(--muted); }
143	  .item[hidden], .cat[hidden] { display: none; }
144	  .qty { display: flex; align-items: center; gap: 8px; }
145	  .qty input { width: 64px; text-align: center; }
146	  .qty label { font-size: 13px; color: var(--muted); }
147	  .step { display: none; align-items: center; border: 1px solid var(--line-2); border-radius: 999px; background: var(--paper); }
148	  .step button { width: 38px; height: 38px; border: 0; background: none; font: inherit; font-size: 20px; line-height: 1;
149	    cursor: pointer; color: var(--ink); border-radius: 999px; }
150	  .step output { min-width: 22px; text-align: center; font-weight: 700; font-variant-numeric: tabular-nums; }
151	  .add { display: none; }
152	  .js .qty input, .js .qty label { display: none; }
153	  .js .add { display: inline-flex; }
154	  .js .chosen .add { display: none; }
155	  .js .chosen .step { display: inline-flex; }
156	  .extras-note { font-size: 14px; color: var(--muted); margin: -4px 0 10px; }
157	  {% for n in range(6) %}
158	  .c{{ n }} .dot { background: var(--c{{ n }}-ink); }
159	  .c{{ n }}.chip { background: var(--c{{ n }}-bg); color: var(--c{{ n }}-ink); }
160	  .c{{ n }} .cat-h { color: var(--c{{ n }}-ink); }
161	  {% endfor %}
162	
163	  /* Order panel */
164	  .panel { background: var(--paper); border: 1px solid var(--line); border-radius: var(--radius); box-shadow: var(--shadow); padding: 20px; scroll-margin-top: 76px; }
165	  .panel h2 { font-family: var(--serif); font-size: 24px; margin: 0 0 4px; }
166	  .basket { list-style: none; margin: 12px 0; padding: 0; font-size: 15px; }
167	  .basket li { display: flex; justify-content: space-between; gap: 12px; padding: 6px 0; }
168	  .basket .empty { color: var(--muted); }
169	  .basket li > span:last-child { flex: none; white-space: nowrap; font-variant-numeric: tabular-nums; }
170	  .total { display: flex; justify-content: space-between; border-top: 1px dashed var(--line-2); padding-top: 10px; font-weight: 700; font-size: 17px; }
171	  .facts-sm { list-style: none; padding: 0; margin: 12px 0 0; font-size: 14px; color: var(--ink-2); display: grid; gap: 6px; }
172	  .facts-sm li { display: flex; gap: 8px; }
173	  .facts-sm svg { width: 16px; height: 16px; flex: none; margin-top: 3px; color: var(--muted); }
174	  .field { display: grid; gap: 6px; margin-top: 14px; }
175	  .field label { font-weight: 600; font-size: 15px; }
176	  .field small { color: var(--muted); font-size: 13px; }
177	  input, textarea { font: inherit; padding: 11px 12px; border: 1px solid var(--line-2); border-radius: var(--radius-sm);
178	    background: #fff; color: var(--ink); width: 100%; }
179	  input:focus, textarea:focus { outline: none; border-color: var(--ink); box-shadow: 0 0 0 3px rgba(29,26,22,.12); }
180	  .qty input { width: 64px; }
181	  .hint { font-size: 13px; color: var(--muted); }
182	  .error { background: #fef2f2; color: #991b1b; border: 1px solid #fecaca; padding: 10px 12px; border-radius: var(--radius-sm); margin: 10px 0 0; }
183	  .hp { position: absolute; left: -9999px; width: 1px; height: 1px; overflow: hidden; }
184	
185	  /* Sticky basket bar (phones, with JS) */
186	  .bar-order { position: fixed; left: 12px; right: 12px; bottom: 12px; z-index: 20; display: none; }
187	  .bar-order a { display: flex; justify-content: space-between; align-items: center; gap: 12px; padding: 14px 18px;
188	    border-radius: 16px; background: var(--primary); color: #fff; text-decoration: none; font-weight: 600;
189	    box-shadow: 0 12px 30px -10px rgba(0,0,0,.45); }
190	  .bar-order.show { display: block; }
191	  @media (min-width: 960px) { .bar-order.show { display: none; } }
192	  body.has-bar { padding-bottom: 84px; }
193	  @media (min-width: 960px) { body.has-bar { padding-bottom: 0; } }
194	
195	  /* Info blocks */
196	  .info { display: grid; gap: 14px; margin-top: 8px; }
197	  @media (min-width: 640px) { .info { grid-template-columns: 1fr 1fr; } }
198	  .tile { background: var(--paper); border: 1px solid var(--line); border-radius: var(--radius); padding: 18px; }
199	  .tile h3 { margin: 0 0 6px; font-size: 13px; letter-spacing: .07em; text-transform: uppercase; color: var(--muted); }
200	  .tile p { margin: 0; }
201	  .tile .links { display: flex; flex-wrap: wrap; gap: 8px; margin-top: 10px; }
202	  .tile.wide { grid-column: 1 / -1; }
203	  .pay { display: grid; grid-template-columns: 120px minmax(0, 1fr); gap: 16px; align-items: center; }
204	  .pay svg { width: 120px; height: 120px; background: #fff; border-radius: 10px; border: 1px solid var(--line); }
205	  .upi-id { overflow-wrap: anywhere; font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace; font-size: 14px; background: var(--bg); padding: 2px 8px; border-radius: 6px; }
206	  .upi-name { font-size: 14px; color: var(--ink-2); margin-top: 6px !important; }
207	  .about { margin-top: 36px; }
208	  .prose { max-width: 40em; color: var(--ink-2); font-size: 17px; }
209	  .prose p { margin: 0 0 12px; }
210	
211	  footer { border-top: 1px solid var(--line); color: var(--muted); font-size: 14px; padding: 24px 0 32px; }
212	  footer .wrap { display: flex; flex-wrap: wrap; justify-content: space-between; gap: 8px 20px; }
213	  footer a { color: var(--ink-2); }
214	
215	  /* Thanks / privacy */
216	  .narrow { max-width: 680px; }
217	  .done-mark { width: 56px; height: 56px; border-radius: 18px; display: grid; place-items: center; background: var(--c1-bg); color: var(--c1-ink); }
218	  .done-mark svg { width: 28px; height: 28px; }
219	  /* S10.5: the owner's category picks the main colour (food warm, handmade plum, custom indigo). */
220	  .niche-food { --primary: #7c2d12; }
221	  .niche-handmade { --primary: #6b2150; }
222	  .niche-custom { --primary: #1e3a8a; }
223	</style>
