463	<script>
464	/* Basket: enhances the plain quantity boxes (the form works without this). Totals here are for display;
465	   the server works out the real total from the menu. */
466	(function () {
467	  document.documentElement.classList.add("js");
468	  var form = document.getElementById("order-form");
469	  if (!form) return;
470	  var inr = function (n) {
471	    var s = String(Math.round(n)), head = s.slice(0, -3), tail = s.slice(-3);
472	    return "₹" + (head ? head.replace(/\B(?=(\d\d)+(?!\d))/g, ",") + "," + tail : tail);
473	  };
474	  var rows = Array.prototype.slice.call(form.querySelectorAll(".item"));
475	  var basket = document.getElementById("basket"), totalRow = document.getElementById("total-row");
476	  var bar = document.getElementById("bar-order");
477	  function val(input) { var n = parseInt(input.value, 10); return isNaN(n) || n < 0 ? 0 : Math.min(n, 50); }
478	  function refresh() {
479	    var count = 0, total = 0, lines = [];
480	    rows.forEach(function (row) {
481	      var input = row.querySelector("input"), n = val(input);
482	      row.classList.toggle("chosen", n > 0);
483	      row.querySelector("output").textContent = n;
484	      if (n > 0) {
485	        count += n; total += n * Number(input.dataset.price);
486	        var li = document.createElement("li"), a = document.createElement("span"), b = document.createElement("span");
487	        a.textContent = n + " × " + input.dataset.name; b.textContent = inr(n * Number(input.dataset.price));
488	        li.appendChild(a); li.appendChild(b); lines.push(li);
489	      }
490	    });
491	    basket.innerHTML = "";
492	    if (lines.length) { lines.forEach(function (li) { basket.appendChild(li); }); }
493	    else { var e = document.createElement("li"); e.className = "empty"; e.textContent = "Add items from the menu."; basket.appendChild(e); }
494	    totalRow.hidden = !count;
495	    document.getElementById("total").textContent = inr(total);
496	    document.getElementById("bar-count").textContent = count + (count === 1 ? " item" : " items");
497	    document.getElementById("bar-total").textContent = inr(total);
498	    bar.classList.toggle("show", count > 0);
499	    document.body.classList.toggle("has-bar", count > 0);
500	  }
501	  rows.forEach(function (row) {
502	    var input = row.querySelector("input");
503	    var set = function (n) { input.value = Math.max(0, Math.min(50, n)); refresh(); };
504	    row.querySelector(".add").addEventListener("click", function () { set(1); row.querySelector(".plus").focus(); });
505	    row.querySelector(".plus").addEventListener("click", function () { set(val(input) + 1); });
506	    row.querySelector(".minus").addEventListener("click", function () {
507	      set(val(input) - 1); if (!val(input)) row.querySelector(".add").focus();
508	    });
509	  });
510	  refresh();
511	  var find = document.getElementById("find");
512	  if (find) {
513	    find.hidden = false;
514	    var box = document.getElementById("find-input"), none = document.getElementById("find-none");
515	    box.addEventListener("input", function () {
